{
  "sql": "SELECT COALESCE(t.product_category_name_english, 'sin_categoria') AS categoria, ROUND(SUM(oi.freight_value) * 100.0 / SUM(oi.price), 2) AS porcentaje_flete FROM order_items oi JOIN products p ON oi.product_id = p.product_id LEFT JOIN product_category_translation t ON t.product_category_name = p.product_category_name WHERE oi.price + oi.freight_value >= 5000 GROUP BY categoria ORDER BY porcentaje_flete DESC LIMIT 3"
}
